class InvokeSshHandler:
    def __init__(
            self,
            smod_ip='192.168.255.129',
            username='toor4nsn',
            password='oZPS0POrRieRtu',
            proxy_vm_address=None,
            proxy_vm_username='ute'
    ):
        self._smod_ip = smod_ip
        self._smod_username = username
        self._smod_password = password
        self._slave_bts = False
        self._session = None
        self._channel = None
        self._master_bts_alias = None
        self._slave_bts_alias = None
        self._proxy_vm_address = proxy_vm_address
        self._proxy_vm_username = proxy_vm_username

    @property
    def session(self):
        """
        SSHClient session
        """
        if self._session is None:
            os.system(f"ssh-keygen -R {self._smod_ip} >/dev/null 2>&1")
            self._session = paramiko.SSHClient()
            self._session.load_system_host_keys()
            self._session.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            if self._proxy_vm_address is not None:
                proxy_cmd = paramiko.ProxyCommand(
                    "ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null "
                    f"{self._proxy_vm_username}@{self._proxy_vm_address} -W {self._smod_ip}:22"
                )
                log_operation(f"Connecting to SMOD via SSH proxy VM: {self._proxy_vm_address}")
                self._session.connect(
                    hostname=self._smod_ip,
                    username=self._smod_username,
                    password=self._smod_password,
                    sock=proxy_cmd,
                )
            else:
                self._session.connect(
                    hostname=self._smod_ip, username=self._smod_username, password=self._smod_password
                )
            self._master_bts_alias = self._get_master_bts_alias()
            self._slave_bts_alias = None

        return self._session

    @property
    def channel(self):
        """
        Channel connected to the remote shell session on the SSH server
        """
        if self._channel is None:
            self._channel = self.session.invoke_shell()

        return self._channel

    @property
    def master_bts_alias(self):
        """
        Gets master bts alias.
        """
        if self._master_bts_alias is None:
            self._master_bts_alias = self._get_master_bts_alias()

        return self._master_bts_alias

    @property
    def slave_bts_alias(self):
        """
        Gets slave bts alias based on master bts alias.
        """
        if self._slave_bts_alias is None:
            self._slave_bts_alias = self._get_slave_bts_alias(self.master_bts_alias)

        return self._slave_bts_alias

    @log_input_and_output
    def check_session_to_particular_bts_side_and_reconnect_session_if_needed(self, slave_bts):
        """
        Checks if session exists on proper system module side and makes new connection if needed.
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        """
        if slave_bts != self._slave_bts:
            self.close_connection()
            if slave_bts:
                self._connect_to_slave_bts()
            self._slave_bts = slave_bts

    @log_input_and_output
    def reconnect_ssh_session(self):
        """
        Reconnects ssh session.
        """
        self.close_connection()
        log_result("Session has been closed.")
        self.reconnect_channel_session()

        return self._session

    @log_input_and_output
    def reconnect_channel_session(self):
        """
        Reconnects invoke shell channel on existing ssh session.
        """
        self._channel = self.session.invoke_shell()
        log_operation("Invoke channel session has been reconnected: {}".format(self._channel))
        return self._channel

    @log_input_and_output
    def connect_to_fhnet(self, container=None, timeout=5, slave_bts=False):
        """
        Connect to FHNET container through invoke shell terminal
        :param container: FHNET container address to which to connect (0x1018 or 0x2018).
                          Default value is None which means lxc-ls command output will be checked
        :type container: str
        :param timeout: Allowed time in seconds to establish connection. Default is 5s
        :type timeout: int
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        :return: True when connected to FHNET
        :rtype: bool
        :raises FHNETConnectionError exception when connection not established
        """
        self.check_session_to_particular_bts_side_and_reconnect_session_if_needed(slave_bts)

        smod_header = "root@{}:".format(self.slave_bts_alias) if slave_bts else "root@{}:".format(self.master_bts_alias)

        ssh_output = self._send_command_and_return_output(command='\r\n', timeout=timeout)
        if "root@FHNET" in ssh_output:
            self._verify_bts_side_for_connected_container(smod_header)
            log_result('Successfully connected to FHNET')
            return True
        if smod_header not in ssh_output:
            exit_try = self._try_to_logout_by_exit(timeout=timeout)
            if "root@FHNET" in exit_try:
                self._verify_bts_side_for_connected_container(smod_header)
                log_result('Successfully connected to FHNET')
                return True

        if not container:
            container = self._get_fhnet_container()

        cmd_to_fhnet = "lxc-attach --name {}".format(container)
        lxc_attach = self._send_command_and_return_output(command=cmd_to_fhnet, timeout=timeout)
        if "root@FHNET" in lxc_attach:
            self._verify_bts_side_for_connected_container(smod_header)
            log_result('Successfully connected to FHNET')
            return True

        raise FHNETConnectionError("Could NOT connect to FHNET \n {}".format(lxc_attach))

    @log_input_and_output
    def connect_to_rmod(self, ip, username, password, container=None, timeout=7, slave_bts=False, switch_to_rfsw=True):
        """
        Connect to RMOD via container through invoke shell terminal
        :param ip: RMOD ip address
        :type ip: str
        :param username: RMOD username to set up ssh connection
        :type username: str
        :param password: RMOD password to set up ssh connection
        :type password: str
        :param container: FHNET container address to which to connect (0x1018 or 0x2018).
                          Default value is None which means lxc-ls command output will be checked
        :type container: str
        :param timeout: Allowed time in seconds to establish an ssh connection. Default is 7s
        :type timeout: int
        :param slave_bts: Used for fullrack configuration only. True if connection should be performed to slave bts,
                          False in case of master bts connection or configurations other than fullrack.
                          Defaults to False.
        :type slave_bts: bool
        :param switch_to_rfsw: True if additional RMOD's user switch from 'serviceuser' to 'rfsw' should be performed, False otherwise.
                               Defaults to True.
        :type switch_to_rfsw: bool
        :return: True if connection to RMOD was successful
        :rtype: bool
        :raises RmodConnectionError: exception when connection could not be established
        """
        self.connect_to_fhnet(container=container, slave_bts=slave_bts)
        commands = {'ssh_to_rmod': "ssh {}@{}".format(username, ip),
                    'rmod_password': password,
                    'check_if_ip': "ip a | grep {}".format(ip)}
        shell_stdout = self._send_command_and_return_output(commands['ssh_to_rmod'], timeout=6, repetition_interval=3)
        buff_shell_stdout = shell_stdout

        while timeout > 0:
            time.sleep(1)
            timeout -= 1
            if "(yes/no/[fingerprint])" in shell_stdout:
                shell_stdout = self._send_command_and_return_output('yes')
            elif "IT IS POSSIBLE THAT SOMEONE IS DOING SOMETHING NASTY!" in shell_stdout:
                shell_stdout = self._send_command_and_return_output('rm /user/toor4nsn/.ssh/known_hosts')
                shell_stdout += self._send_command_and_return_output(commands['ssh_to_rmod'], timeout=6,
                                                                     repetition_interval=3)
            else:
                shell_stdout += self._provide_password_and_get_stdout_if_needed(shell_stdout=shell_stdout,
                                                                                password=password)

                if self._check_if_login_succeeded(ip):
                    if username == "serviceuser" and switch_to_rfsw:
                        self._switch_to_rfsw_from_serviceuser()
                    return True
                else:
                    shell_stdout = self._send_command_and_return_output(commands['ssh_to_rmod'], timeout=6,
                                                                        repetition_interval=3)

            buff_shell_stdout += shell_stdout

        raise RmodConnectionError("""Error Unable to connect to RMOD {}\n
                                  --OUTPUT from terminal----\n {}""".format(ip, buff_shell_stdout))

